<script setup lang="ts">
import { computed, inject } from "vue";
import type { MessageInputPart } from "@/api/types";
import { inputPartsBlocks } from "@/agent/orderedInput";
import { workspaceFileNavigationKey } from "@/agent/workspaceFileNavigation";
import OrderedMessageContent from "./OrderedMessageContent.vue";
import ShortcutDetails from "./ShortcutDetails.vue";
import CodeBlock from "./CodeBlock.vue";
import AnswerText from "./AnswerText.vue";
import { Icon } from "@iconify/vue";
import { starterIconFor } from "./starterIcons";
const props = defineProps<{ parts: MessageInputPart[]; language?: string }>();
const rows = computed(() => props.parts.map(part => ({ part, blocks: inputPartsBlocks([part]) })));
const navigation = inject(workspaceFileNavigationKey, null);
function openFile(file: { path: string; name: string }) { const scope = navigation?.scope(); if (scope && navigation) navigation.open(file, scope); }
</script>
<template><div class="structured-shortcut-content" data-testid="structured-shortcut-content"><template v-for="({part,blocks},index) in rows" :key="index"><AnswerText v-if="part.type === 'text' && language === 'markdown'" class="shortcut-markdown" :source="part.text" passive /><span v-else-if="part.type === 'text' && (!language || language === 'text')" class="structured-prose">{{ part.text }}</span><CodeBlock v-else-if="part.type === 'text'" :code="part.text" :lang="language || 'text'" uncollapsed preserve-trailing-line /><details v-else-if="part.type === 'shortcut'" class="nested-shortcut"><summary data-reference-kind="shortcut"><Icon v-if="starterIconFor(part.icon)" :icon="starterIconFor(part.icon)!" /><span>{{ part.title }}</span></summary><ShortcutDetails :title="part.title" :content="part.text" :parts="part.parts" :icon="part.icon" :language="part.language" /></details><OrderedMessageContent v-else :blocks="blocks" :parse-skill="false" @open-file="openFile" /></template></div></template>
<style scoped>.shortcut-markdown{min-width:0;max-width:100%;white-space:normal;overflow-wrap:anywhere}.structured-shortcut-content { display:block; white-space:pre-wrap; overflow-wrap:anywhere; line-height:1.8; min-width:0; max-width:100%; }.structured-prose { white-space:pre-wrap; overflow-wrap:anywhere; }.structured-shortcut-content > :deep(.code-block) { box-sizing:border-box; width:100%; max-width:100%; margin:0; border:0; border-radius:6px; }.structured-shortcut-content > :deep(.code-block .bar){display:none}.structured-shortcut-content > :deep(.code-block pre){white-space:pre-wrap;overflow-wrap:anywhere}.nested-shortcut { box-sizing:border-box; display:inline-block; vertical-align:baseline; min-width:0; max-width:100%; margin:1px 3px; }.nested-shortcut[open] { display:block; width:100%; margin:8px 0; }.nested-shortcut > summary { box-sizing:border-box; display:inline-flex; align-items:center; gap:5px; cursor:pointer; max-width:100%; padding:2px 8px; border:1px solid var(--pg-accent-line); border-radius:7px; color:var(--el-color-primary); background:var(--el-color-primary-light-9); user-select:none; }.nested-shortcut > summary::before {content:'▸';font-size:11px}.nested-shortcut[open]>summary::before{content:'▾'}.nested-shortcut > summary svg{width:15px;height:15px;flex:none}.nested-shortcut > summary span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.nested-shortcut > .shortcut-details{--shortcut-details-max-height:none;margin:10px 0 2px;padding:10px 12px;border-left:2px solid var(--pg-accent-line);background:var(--el-fill-color-lighter);border-radius:0 8px 8px 0}.nested-shortcut > :deep(.shortcut-details .shortcut-details-body){max-height:none;overflow:visible;scrollbar-gutter:auto}.nested-shortcut > :deep(.shortcut-details .shortcut-details-heading small),.nested-shortcut > :deep(.shortcut-details footer p){display:none}</style>
